def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    sep_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    sep_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    def ranges(size, separators):
        result = []
        start = 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < size:
            result.append((start, size))
        return result

    row_ranges = ranges(h, sep_rows)
    col_ranges = ranges(w, sep_cols)
    blocks = [
        (r0, r1, c0, c1)
        for r0, r1 in row_ranges
        for c0, c1 in col_ranges
    ]

    divider_colors = {grid[r][0] for r in sep_rows}
    divider_colors.update(grid[0][c] for c in sep_cols)

    def filled_count(block):
        r0, r1, c0, c1 = block
        return sum(
            grid[r][c] != background and grid[r][c] not in divider_colors
            for r in range(r0, r1)
            for c in range(c0, c1)
        )

    source = max(blocks, key=filled_count)
    sr0, sr1, sc0, sc1 = source
    pattern = [grid[r][sc0:sc1] for r in range(sr0, sr1)]

    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in blocks:
        if (r1 - r0, c1 - c0) == (len(pattern), len(pattern[0])):
            for i in range(len(pattern)):
                out[r0 + i][c0:c1] = pattern[i][:]
    return out
